#!/usr/bin/env python3
"""Generate native zRPC headers from .rpc protocol tables + .proto messages."""

from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

IDENTIFIER = r"[A-Za-z_][A-Za-z0-9_]*"
PACKAGE = rf"{IDENTIFIER}(?:\.{IDENTIFIER})*"
PACKAGE_LINE = re.compile(rf"^\s*package\s+({PACKAGE})\s*$")
PROTO_LINE = re.compile(r"^\s*proto\s+(\S+)\s*$")
RPC_LINE = re.compile(
    rf"^\s*rpc\s+({IDENTIFIER})\s+(\d+)\s+({IDENTIFIER})\s+({IDENTIFIER})\s*$"
)
LEGACY_RPC_LINE = re.compile(
    rf"^\s*rpc\s+({IDENTIFIER})\s*\(\s*({IDENTIFIER})\s*\)\s*"
    rf"returns\s*\(\s*({IDENTIFIER})\s*\)\s*;\s*"
    r"(?://\s*zrpc_id\s*=\s*(\d+))?\s*$"
)


def validate_rpcs(
    path: Path, rpcs: list[tuple[str, str, str, int]]
) -> None:
    methods: set[str] = set()
    protocol_ids: set[int] = set()
    for method, _, _, protocol_id in rpcs:
        if method in methods:
            raise ValueError(f"{path}: duplicate rpc method {method}")
        if protocol_id in protocol_ids:
            raise ValueError(f"{path}: duplicate protocol id {protocol_id}")
        if not 0 <= protocol_id <= 0xFFFFFFFF:
            raise ValueError(
                f"{path}: protocol id {protocol_id} is outside uint32 range"
            )
        methods.add(method)
        protocol_ids.add(protocol_id)


def parse_rpc_file(path: Path) -> tuple[str, str, list[tuple[str, str, str, int]]]:
    package = ""
    proto_file = ""
    rpcs: list[tuple[str, str, str, int]] = []

    for line_number, raw in enumerate(
        path.read_text(encoding="utf-8").splitlines(), start=1
    ):
        line = raw.split("#", 1)[0].strip()
        if not line:
            continue

        match = PACKAGE_LINE.match(line)
        if match:
            if package:
                raise ValueError(f"{path}:{line_number}: duplicate package")
            package = match.group(1)
            continue

        match = PROTO_LINE.match(line)
        if match:
            if proto_file:
                raise ValueError(f"{path}:{line_number}: duplicate proto")
            proto_file = match.group(1)
            continue

        match = RPC_LINE.match(line)
        if match:
            method, protocol_id, request, response = match.groups()
            rpcs.append((method, request, response, int(protocol_id)))
            continue

        raise ValueError(f"{path}:{line_number}: invalid directive: {line}")

    if not package:
        raise ValueError(f"{path}: missing package")
    if not proto_file:
        proto_file = path.with_suffix(".proto").name
    if not rpcs:
        raise ValueError(f"{path}: no rpc entries found")

    validate_rpcs(path, rpcs)
    return package, proto_file, rpcs


def parse_legacy_service_proto(path: Path) -> tuple[str, str, list[tuple[str, str, str, int]]]:
    text = path.read_text(encoding="utf-8")
    package_match = re.search(
        rf"^\s*package\s+({PACKAGE})\s*;\s*$", text, re.M
    )
    if not package_match:
        raise ValueError(f"{path}: missing package declaration")
    package = package_match.group(1)

    rpcs: list[tuple[str, str, str, int]] = []
    next_auto_id = 1001
    for line in text.splitlines():
        match = LEGACY_RPC_LINE.match(line)
        if not match:
            continue
        method, request, response, explicit_id = match.groups()
        protocol_id = int(explicit_id) if explicit_id else next_auto_id
        rpcs.append((method, request, response, protocol_id))
        if explicit_id is None:
            next_auto_id += 1
        else:
            next_auto_id = max(next_auto_id, protocol_id + 1)

    if not rpcs:
        raise ValueError(f"{path}: no service rpc methods found")
    validate_rpcs(path, rpcs)
    return package, path.name, rpcs


def stem_to_pascal(stem: str) -> str:
    return "".join(part.capitalize() for part in stem.split("_"))


def generate_header(
    stem: str, package: str, proto_file: str, rpcs: list[tuple[str, str, str, int]]
) -> str:
    pb_header = Path(proto_file).with_suffix(".pb.h").as_posix()
    module = stem_to_pascal(stem)
    if not re.fullmatch(IDENTIFIER, module):
        raise ValueError(f"invalid generated C++ module name: {module}")
    handler_name = f"{module}RpcHandler"
    client_name = f"{module}RpcClient"
    register_fn = f"Register{module}Rpc"

    lines = [
        "// Generated by gen_zrpc.py from native .rpc protocol table. DO NOT EDIT.",
        "#pragma once",
        "",
        "#include <functional>",
        "#include <string>",
        "#include <utility>",
        "",
        f'#include "{pb_header}"',
        '#include "zrpc/rpc/client.h"',
        '#include "zrpc/rpc/protocol.h"',
        '#include "zrpc/rpc/server.h"',
        "",
        f"namespace {package.replace('.', '::')} {{",
        "",
        "enum class Protocol : zrpc::rpc::ProtocolId {",
    ]

    for method, _, _, protocol_id in rpcs:
        lines.append(f"  k{method} = {protocol_id},")

    lines.extend(
        [
            "};",
            "",
            f"class {handler_name} {{",
            " public:",
            f"  virtual ~{handler_name}() = default;",
        ]
    )

    for method, request, response, _ in rpcs:
        lines.append(
            f"  virtual zrpc::rpc::Reply {method}(const {request}& request, "
            f"{response}* response) = 0;"
        )

    lines.extend(
        [
            "};",
            "",
            f"inline void {register_fn}(zrpc::rpc::Server* server, {handler_name}* handler) {{",
            "  if (server == nullptr || handler == nullptr) {",
            "    return;",
            "  }",
        ]
    )

    for method, request, response, protocol_id in rpcs:
        lines.extend(
            [
                f"  zrpc::rpc::RegisterProto<{request}, {response}>(",
                f"      server, static_cast<zrpc::rpc::ProtocolId>(Protocol::k{method}),",
                f"      [handler](const {request}& request, {response}* response) {{",
                f"        return handler->{method}(request, response);",
                "      });",
            ]
        )

    lines.extend(
        [
            "}",
            "",
            f"class {client_name} {{",
            " public:",
            f"  explicit {client_name}(zrpc::rpc::Client* client) : client_(client) {{}}",
            "",
        ]
    )

    for method, request, response, _ in rpcs:
        lines.extend(
            [
                f"  zrpc::rpc::Reply {method}(const {request}& request, {response}* response,",
                "                            const zrpc::rpc::CallOptions& options = {}) {",
                f"    return zrpc::rpc::CallProto<{request}, {response}>(",
                f"        client_, static_cast<zrpc::rpc::ProtocolId>(Protocol::k{method}),",
                "        request, response, options);",
                "  }",
                "",
                f"  void {method}Async(",
                f"      const {request}& request,",
                f"      std::function<void(const zrpc::rpc::Reply&, const {response}&)> callback,",
                "      const zrpc::rpc::CallOptions& options = {}) {",
                f"    zrpc::rpc::AsyncCallProto<{request}, {response}>(",
                f"        client_, static_cast<zrpc::rpc::ProtocolId>(Protocol::k{method}),",
                "        request, std::move(callback), options);",
                "  }",
                "",
            ]
        )

    lines.extend(
        [
            " private:",
            "  zrpc::rpc::Client* client_;",
            "};",
            "",
            f"}}  // namespace {package.replace('.', '::')}",
            "",
        ]
    )
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Generate native zRPC headers from .rpc protocol tables"
    )
    parser.add_argument(
        "input",
        type=Path,
        help="input .rpc protocol table (or legacy .proto with service)",
    )
    parser.add_argument("-o", "--output", type=Path, help="output .zrpc.h file")
    args = parser.parse_args()

    if args.input.suffix == ".rpc":
        package, proto_file, rpcs = parse_rpc_file(args.input)
        stem = args.input.stem
    elif args.input.suffix == ".proto":
        package, proto_file, rpcs = parse_legacy_service_proto(args.input)
        stem = args.input.stem
        print(
            f"warning: {args.input} uses legacy grpc-style service; "
            f"prefer a separate .rpc file for native zRPC",
            file=sys.stderr,
        )
    else:
        raise ValueError("input must be .rpc or legacy .proto")

    output = args.output or args.input.with_suffix(".zrpc.h")
    output.write_text(generate_header(stem, package, proto_file, rpcs), encoding="utf-8")
    print(f"generated {output}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
